args.sparql:
SELECT DISTINCT ?artist ?artistLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Changed_It dbo:artist ?artist .
  OPTIONAL { ?artist dbo:birthPlace ?birthPlace . }
  OPTIONAL { ?artist rdfs:label ?artistLabel FILTER (lang(?artistLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = "en") }
}

SELECT DISTINCT ?artist ?artistLabel ?birthPlace ?birthPlaceLabel WHERE {
  BIND(dbr:Nicki_Minaj AS ?artist) .
  ?artist dbo:birthPlace ?birthPlace .
  OPTIONAL { ?artist rdfs:label ?artistLabel FILTER (lang(?artistLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = "en") }
}

